use super::*;
struct Round{source:EpochFixture,source_choices:Choices,target:Temp,owner:Harness,workspace:PathBuf,id:String}
impl Round{
 fn new()->Self{let(source,source_choices)=prepared();admit(&source,&source_choices);let storage=active(&source).unwrap().into_storage().unwrap();let paths=storage.paths().unwrap();fs::write(paths.data.join("assistant/conversations.json"),br#"{"version":4,"pets":{"codex":{"id":"third-current","created":5,"updated":6,"messages":[],"session":{"id":"third-native","cwd":"/private-fixture","full_access":false},"tasks":[]}},"archives":{}}"#).unwrap();source.target.file(&paths.data.join("inbox/third-current.bin"),b"new work after admission3");source.target.file(&paths.config.join("pet-runtime-results-v1/third-unknown.json"),br#"{"phase":"uncertain","observedConsumption":null}"#);drop(storage);let workspace=source.target.0.join("third-backups");fs::DirBuilder::new().mode(0o700).create(&workspace).unwrap();let r=current_profile::Review::capture(active(&source).unwrap(),&workspace).unwrap();let fp=r.fingerprint().unwrap();let id=r.copy(&fp).unwrap().0;let target=Temp::new();let layout=target.layout();for p in [&layout.legacy_config,&layout.legacy_data]{fs::DirBuilder::new().recursive(true).mode(0o700).create(p).unwrap();}Self{source,source_choices,target,owner:Harness::new(),workspace,id}}
 fn archive(&self)->PathBuf{self.workspace.join(format!("current-profile-{}",self.id))}
 fn review(&self,mode:Mode)->Result<Review>{let layout=self.target.layout();Review::capture(self.owner.claim(&layout)?,layout,&self.workspace,&self.id,mode)}
 fn initialize_data(&self){let r=self.review(Mode::Fresh).unwrap();let v=r.preview().unwrap();assert_eq!(v["archiveVersion"],2);assert_eq!(v["destinationProfileVersion"],3);assert_eq!(v["operationalPayloadDepth"],3);r.apply(v["fingerprint"].as_str().unwrap()).unwrap();}
 fn configured(&self)->Choices{self.initialize_data();let r=self.review(Mode::Resume).unwrap().authority().unwrap();let v=r.preview().unwrap();assert_eq!(v["authority"]["historyEpochs"],3);r.apply(v["fingerprint"].as_str().unwrap()).unwrap();let r=self.review(Mode::Resume).unwrap().configuration().unwrap();let v=r.preview().unwrap();assert_eq!(v["operationalPayloadDepth"],3);assert_eq!(v["scope"]["references"]["lineage"].as_array().unwrap().len(),2);let receipt=r.apply(v["fingerprint"].as_str().unwrap()).unwrap();let mut c=self.source_choices.clone();c.inspection_receipt=receipt["receiptHash"].as_str().unwrap().into();c.main_pet="ai_lmstudio".into();c}
 fn activation(&self,c:&Choices)->Result<Activation>{Activation::capture(self.owner.claim(&self.target.layout())?,self.target.layout(),&self.workspace,&self.id,c.clone())}
 fn active(&self)->Result<Active>{Active::open(self.owner.claim(&self.target.layout())?,self.target.layout())}
}
#[test]fn backup3_contains_complete_current_roots_unknown_data_and_all_originals_and_inspects_without_source(){
 let r=Round::new();for (area,path)in[("config",r.source.target.layout().config()),("data",r.source.target.layout().data())]{assert_eq!(private_tree_bytes(&r.archive().join(area)),private_tree_bytes(path));}assert!(r.archive().join("config/.restore-admission/history.json").is_file());assert!(r.archive().join("config/.restore-activation/originals/config/.admitted.json").is_file());assert_eq!(fs::read(r.archive().join("data/payload/payload/inbox/third-current.bin")).unwrap(),b"new work after admission3");let config=r.source.target.layout().config().to_owned();let data=r.source.target.layout().data().to_owned();fs::rename(config,r.source.target.0.join("original-source3-config-offline")).unwrap();fs::rename(data,r.source.target.0.join("original-source3-data-offline")).unwrap();let inspection=staging::inspect_current(&r.workspace,&r.id).unwrap();assert_eq!(inspection.phase,staging::Phase::VerifiedData);assert_eq!(inspection.source_payload_depth,Some(2));assert!(staging::CurrentArchive::open(&r.workspace,&r.id).is_err());
}
#[test]fn restored_source3_keeps_header3_but_uses_depth3_and_denies_every_generation_before_new_work(){
 let r=Round::new();let c=r.configured();let before=private_tree_bytes(&r.target.layout().config().join(JOB));let a=r.activation(&c).unwrap();let v=a.preview().unwrap();assert_eq!(a.manifest.epoch.as_ref().unwrap().payload_depth,3);let first=a.apply(v["fingerprint"].as_str().unwrap()).unwrap();assert_eq!(first["runtimeActivationAvailable"],true);assert_eq!(private_tree_bytes(&r.target.layout().config().join(JOB)),before);let storage=r.active().unwrap().into_storage().unwrap();let paths=storage.paths().unwrap();assert_eq!(paths.config,r.target.layout().config().join("payload/payload/payload"));assert_eq!(paths.data,r.target.layout().data().join("payload/payload/payload"));let h=storage.restored_history().unwrap().unwrap();for id in ["old-current","second-current","third-current"]{assert!(h.conversation_allowed("codex",id,None).is_err());}for id in ["old-native","second-native","third-native"]{assert!(h.native_session_allowed("codex",id).is_err());}assert!(h.conversation_allowed("codex","fourth-independent",Some("fourth-native")).is_ok());assert_eq!(fs::read(paths.config.join("pet-runtime-results-v1/third-unknown.json")).unwrap(),br#"{"phase":"uncertain","observedConsumption":null}"#);assert_eq!(fs::read(paths.data.join("inbox/third-current.bin")).unwrap(),b"new work after admission3");let view=crate::pet_runtime::restoration::historical_view(&paths.config.join("pet-runtime-consent-v1")).unwrap();assert_eq!(view["historyEpochs"],3);
}
#[test]fn next_generation_initialization_staging_resumes_same_custody_and_does_not_reset_local_history(){
 let r=Round::new();let c=r.configured();let before=private_tree_bytes(&r.target.layout().config().join(JOB));let a=r.activation(&c).unwrap();assert!(!a.manifest.changes.is_empty());let fp=a.preview().unwrap()["fingerprint"].as_str().unwrap().to_owned();assert!(a.apply_using(&fp,|s|if s==Step::Staged(0){Err(Error::Unavailable)}else{Ok(())}).is_err());assert!(r.active().is_err());let a=r.activation(&c).unwrap();let fp=a.preview().unwrap()["fingerprint"].as_str().unwrap().to_owned();a.apply(&fp).unwrap();assert_eq!(private_tree_bytes(&r.target.layout().config().join(JOB)),before);let storage=r.active().unwrap().into_storage().unwrap();assert!(storage.restored_history().unwrap().unwrap().native_session_allowed("codex","third-native").is_err());
}
#[test]fn backup3_custody_history_authority_and_originals_tamper_are_refused_without_repair(){
 for name in ["config/.restore-admission/history.json","config/.restore-admission/sealed.json","config/.restore-activation/ready.json","config/.restore-activation/originals/config/.admitted.json","config/payload/payload/pet-runtime-consent-v1/.restored-history.json"]{let r=Round::new();let p=r.archive().join(name);fs::write(&p,b"private altered portable data").unwrap();assert!(staging::inspect_current(&r.workspace,&r.id).is_err());assert_eq!(fs::read(&p).unwrap(),b"private altered portable data");assert!(r.review(Mode::Fresh).is_err());assert!(!r.target.layout().config().exists());}
}
#[test]fn next_generation_review_hash_claim_and_changed_source_prevent_new_wrapper_effects(){
 for mode in ["hash","claim","source"]{let r=Round::new();let a=r.review(Mode::Fresh).unwrap();let mut fp=a.fingerprint().unwrap();match mode{"hash"=>fp="0".repeat(64),"claim"=>r.owner.release(),_=>fs::write(r.archive().join("data/payload/payload/inbox/third-current.bin"),b"different after review").unwrap()};assert!(a.apply(&fp).is_err());assert!(!r.target.layout().config().exists());assert!(!r.target.layout().data().exists());}
}
#[test]fn depth_is_bounded_and_cannot_be_raised_without_the_matching_reference_and_authority_history(){
 let r=Round::new();let config=Dir::root(r.source.target.layout().config()).unwrap();for depth in [0,MAX_PAYLOAD_DEPTH+1]{assert!(payload_at_depth(&config,depth).is_err());}assert!(payload_prefix(MAX_PAYLOAD_DEPTH+1).is_err());let mut m:Manifest=serde_json::from_slice(&fs::read(r.source.target.layout().config().join(EPOCH_JOB).join(MANIFEST)).unwrap()).unwrap();m.epoch.as_mut().unwrap().payload_depth=3;assert!(m.profile_version().is_err());m.epoch.as_mut().unwrap().payload_depth=MAX_PAYLOAD_DEPTH+1;assert!(m.profile_version().is_err());let mut record:Value=serde_json::from_slice(&fs::read(r.archive().join("config/.admitted.json")).unwrap()).unwrap();record["epoch"]["payloadDepth"]=json!(3);fs::write(r.archive().join("config/.admitted.json"),serde_json::to_vec(&record).unwrap()).unwrap();assert!(staging::inspect_current(&r.workspace,&r.id).is_err());assert!(!r.target.layout().config().exists());
}

#[test]fn copy_revision_refuses_source_payload_controls_or_owner_changes_without_publishing_authority(){
 for action in ["source","payload","header","manifest","owner"]{
  let r=Round::new();r.initialize_data();let layout=r.target.layout();let authority=layout.config().join("payload/payload/payload/pet-runtime-consent-v1");let before=private_tree_bytes(&authority);
  let a=r.review(Mode::Resume).unwrap().authority().unwrap();let fp=a.preview().unwrap()["fingerprint"].as_str().unwrap().to_owned();let mut reached=false;
  let crate::pet_data::publication::restore::AuthorityReview::Next(a)=a else{panic!("expected next epoch review")};let result=a.fixture_during_originals(&fp,|index|{if index==1{reached=true;match action{
   "source"=>fs::write(r.archive().join("data/payload/payload/inbox/third-current.bin"),b"changed during copy").unwrap(),
   "payload"=>fs::write(layout.data().join("payload/payload/payload/inbox/third-current.bin"),b"changed during copy").unwrap(),
   "header"=>fs::write(layout.config().join(crate::pet_data::publication::HEADER),b"changed during copy").unwrap(),
   "manifest"=>fs::write(layout.config().join(JOB).join(MANIFEST),b"changed during copy").unwrap(),
   _=>r.owner.release(),
  }}Ok(())});
  assert!(reached,"{action}");assert!(result.is_err(),"{action}");assert!(!layout.config().join(JOB).join(READY).exists(),"{action}");assert_eq!(private_tree_bytes(&authority),before,"{action}");assert!(!layout.config().join(EPOCH_JOB).exists());
 }
}
#[test]fn interrupted_original_copy_resumes_same_custody_under_fresh_phase_review(){
 let r=Round::new();r.initialize_data();let a=r.review(Mode::Resume).unwrap().authority().unwrap();let fp=a.preview().unwrap()["fingerprint"].as_str().unwrap().to_owned();let mut cut=false;
 let crate::pet_data::publication::restore::AuthorityReview::Next(a)=a else{panic!("expected next epoch review")};assert!(a.fixture_during_originals(&fp,|index|{if index==1{cut=true;Err(Error::Unavailable)}else{Ok(())}}).is_err());assert!(cut);assert!(!r.target.layout().config().join(JOB).join(READY).exists());
 let custody=private_tree_bytes(&r.target.layout().config().join(JOB));let manifest=fs::read(r.target.layout().config().join(JOB).join(MANIFEST)).unwrap();
 let a=r.review(Mode::Resume).unwrap().authority().unwrap();let fresh=a.preview().unwrap()["fingerprint"].as_str().unwrap().to_owned();assert_ne!(fresh,fp);assert!(a.apply(&fp).is_err());assert_eq!(private_tree_bytes(&r.target.layout().config().join(JOB)),custody);
 let a=r.review(Mode::Resume).unwrap().authority().unwrap();assert_eq!(a.preview().unwrap()["fingerprint"].as_str(),Some(fresh.as_str()));a.apply(&fresh).unwrap();assert_eq!(fs::read(r.target.layout().config().join(JOB).join(MANIFEST)).unwrap(),manifest);
 for area in ["config","data"]{assert_eq!(private_tree_bytes(&r.target.layout().config().join(JOB).join("originals").join(area)),private_tree_bytes(&r.archive().join(area)));}
 assert!(r.active().is_err());
}
